package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.period.PeriodCloser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class SaveToday {
    public void save(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val LocalDate today,
            SheetClock clock, PeriodCloser closer, Rollup rollup, Claims claims, SheetStates states) {
        Rollup.Snapshot before = rollup.take(sheet);
        // A change of today releases every claim editor's lock on the sheet.
        LocalDate was = clock.today(sheet);
        if (!today.equals(was)) {
            claims.unlockAll(sheet);
            // What the sheet holds at the end of its old today is kept, for a statement taken as of that date.
            states.keep(sheet, was, today);
        }
        clock.setToday(sheet, today);
        // Periods past their grace days close before the figures the today change moved are audited.
        closer.autoClose(sheet, user);
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.sheet;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The sheets a steward has archived. An archived sheet stays visible and refuses every change. */
@Repository
public class SheetArchive {

    private final JdbcTemplate jdbc;

    public SheetArchive(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public boolean archived(String sheet) {
        return jdbc.queryForObject("SELECT COUNT(*) FROM sheet_archive WHERE sheet = ?", Integer.class, sheet) > 0;
    }

    /** Archives the sheet; false when it already was. */
    public boolean archive(String sheet, String user) {
        return jdbc.update("INSERT INTO sheet_archive (sheet, archived_by) SELECT ?, ? WHERE NOT EXISTS "
                + "(SELECT 1 FROM sheet_archive WHERE sheet = ?)", sheet, user, sheet) > 0;
    }
}
package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/**
 * The sheet's "today". Every date decision and every default date in the app reads the date from
 * here, never from the real clock. A sheet starts at the real date until its today is set.
 */
@Service
public class SheetClock {

    private final JdbcTemplate jdbc;

    public SheetClock(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public LocalDate today(String sheet) {
        List<LocalDate> found = jdbc.query("SELECT today FROM sheet WHERE id = ?",
                (rs, i) -> rs.getDate(1).toLocalDate(), sheet);
        return found.isEmpty() ? LocalDate.now() : found.get(0);
    }

    public void setToday(String sheet, LocalDate today) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) VALUES (?, ?)", sheet, Date.valueOf(today));
    }
}
