import { QueryClient } from '@tanstack/react-query';

// Server data is NEVER copied into component state. A feature reads it with useQuery under its own
// key (e.g. ['clients'] / ['project', id, 'notes']) and changes it with useMutation +
// invalidateQueries. Two features share data by sharing a KEY, never by a parent holding it.
// retry:false + no focus refetching keep the e2e runs deterministic.
export const queryClient = new QueryClient({
  defaultOptions: {
    queries: { retry: false, refetchOnWindowFocus: false },
    mutations: { retry: false },
  },
});
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type Sheet = { id: string; today: string; archived: boolean };

export const sheetKey = (sheet: string) => ['sheet', sheet] as const;

/** The sheet's settings, its today among them. Every default date and date decision on screen
 *  reads `today` from here, never from the browser's clock. */
export function useSheet(sheet: string) {
  return useQuery({
    queryKey: sheetKey(sheet),
    queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheet)}`),
  });
}

/** The sheet's today (yyyy-MM-dd), or undefined while it loads. */
export function useSheetToday(sheet: string): string | undefined {
  return useSheet(sheet).data?.today;
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { byUser } from '../session/session';
import { sheetKey, useSheet } from './sheet';
import type { Sheet } from './sheet';

// The sheet's today: shown, and changeable. It starts as the real date. A steward archives the sheet here too;
// both share the sheet's error, and each action clears the other's.
function SheetToday({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const { data } = useSheet(sheet);
  const [draft, setDraft] = useState('');
  const save = useMutation({
    mutationFn: (today: string) =>
      postJson<Sheet>(byUser(`/api/sheets/${encodeURIComponent(sheet)}/today`, user), { today }),
    onSuccess: (updated) => {
      queryClient.setQueryData(sheetKey(sheet), updated);
      // Everything on the sheet may depend on its today: re-read it all.
      void queryClient.invalidateQueries({
        predicate: (q) => q.queryKey.includes(sheet) && q.queryKey[0] !== 'sheet',
      });
    },
  });
  const send = useSubmitOnce(save);
  const archive = useMutation({
    mutationFn: () => postJson<Sheet>(byUser(`/api/sheets/${encodeURIComponent(sheet)}/archive`, user), {}),
    onSuccess: (updated) => queryClient.setQueryData(sheetKey(sheet), updated),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    archive.reset();
    send(draft.trim());
  };

  return (
    <form onSubmit={submit}>
      Today: <strong data-testid="sheet-today">{data?.today ?? ''}</strong>{' '}
      <input
        data-testid="sheet-today-input"
        type="text"
        placeholder="yyyy-mm-dd"
        value={draft}
        onChange={(e) => {
          setDraft(e.target.value);
          save.reset();
          archive.reset();
        }}
      />
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set today
      </button>
      {' '}Archived: <strong data-testid="sheet-archived">{data ? (data.archived ? 'yes' : 'no') : ''}</strong>{' '}
      <button
        type="button"
        data-testid="sheet-archive"
        disabled={archive.isPending}
        onClick={() => {
          save.reset();
          archive.reset();
          archive.mutate();
        }}
      >
        Archive sheet
      </button>
      {(save.isError || archive.isError) && (
        <span data-testid="sheet-error" role="alert">
          {' '}{archive.isError ? 'The sheet could not be archived.' : 'That date was refused.'}
        </span>
      )}
    </form>
  );
}

export const contribution = SheetPanels.fill({ order: 0, Component: SheetToday });
import { asString, useSearchParam } from '../../url/useSearchParam';

// Who is signed in and which sheet is active. Both live in the URL (search params `user` and
// `sheet`), so any feature reads them directly.
export const useCurrentUser = () => useSearchParam('user', asString);
export const useCurrentSheet = () => useSearchParam('sheet', asString);

/** A write's path carrying who made it, so the server can record it in the audit file. */
export const byUser = (path: string, user: string) => `${path}?user=${encodeURIComponent(user)}`;
